// TestClearFilesystemTranscript_RemovesStagedTranscript pins the leak fix: the
// staged full.jsonl is a buffer for the checkpoint writer, so once a session's
// work is condensed it must not stay in the worktree. Before this, nothing ever
// removed it and a few hundred sessions accumulated hundreds of MB.
//
// Not parallel: entiredir resolves the worktree root from the process CWD.
func TestClearFilesystemTranscript_RemovesStagedTranscript(t *testing.T) {
	repoDir := t.TempDir()
	testutil.InitRepo(t, repoDir)
	testutil.WriteFile(t, repoDir, "f.txt", "init")
	testutil.GitAdd(t, repoDir, "f.txt")
	testutil.GitCommit(t, repoDir, "init")
	t.Chdir(repoDir)

	const sessionID = "session-clear-transcript"
	metaDir := filepath.Join(repoDir, paths.SessionMetadataDirFromSessionID(sessionID))
	require.NoError(t, os.MkdirAll(metaDir, 0o750))

	transcript := filepath.Join(metaDir, paths.TranscriptFileName)
	legacy := filepath.Join(metaDir, paths.TranscriptFileNameLegacy)
	prompt := filepath.Join(metaDir, paths.PromptFileName)
	for _, p := range []string{transcript, legacy, prompt} {
		require.NoError(t, os.WriteFile(p, []byte(`{"x":1}`+"\n"), 0o600))
	}

	clearFilesystemTranscript(context.Background(), sessionID)

	assert.NoFileExists(t, transcript, "full.jsonl should be removed after condensation")
	assert.NoFileExists(t, legacy, "a legacy full.log written by an older CLI should be removed too")
	// clearFilesystemPrompt owns prompt.txt; this helper must not reach past its
	// own two files, and the metadata directory itself has to survive (the next
	// Stop writes into it).
	assert.FileExists(t, prompt, "prompt.txt is clearFilesystemPrompt's to remove, not this one's")
	assert.DirExists(t, metaDir, "the session metadata directory must survive")
}

// TestClearFilesystemTranscript_MissingFilesAreNotAnError covers the ordinary
// steady state after the first condensation: the files are already gone, and a
// later commit for the same session must not fail or panic.
func TestClearFilesystemTranscript_MissingFilesAreNotAnError(t *testing.T) {
	repoDir := t.TempDir()
	testutil.InitRepo(t, repoDir)
	testutil.WriteFile(t, repoDir, "f.txt", "init")
	testutil.GitAdd(t, repoDir, "f.txt")
	testutil.GitCommit(t, repoDir, "init")
	t.Chdir(repoDir)

	// No metadata directory at all, then an empty one.
	clearFilesystemTranscript(context.Background(), "session-never-staged")

	metaDir := filepath.Join(repoDir, paths.SessionMetadataDirFromSessionID("session-empty"))
	require.NoError(t, os.MkdirAll(metaDir, 0o750))
	clearFilesystemTranscript(context.Background(), "session-empty")
	assert.DirExists(t, metaDir)
}
