python3 - <<'PY'
p='cmd/entire/cli/doctor.go'
s=open(p).read()
old='''		// One pass: Repair reports whether it found the rule, so a separate
		// detect call would only read and parse the same file twice.
		changed, repairErr := agent.RepairRetiredMetadataDenyRule(ctx, ag)
		displayName := string(ag.Type())
		switch {
		case repairErr != nil:
			// Reachable only because nothing gates this call. Say what could not
			// be determined rather than claiming a stale rule was found — the
			// config may not carry one at all.
			fmt.Fprintf(w, "%s permissions: UNREADABLE\\n", displayName)
			fmt.Fprintf(w, "  Could not check for the retired Entire deny rule: %v\\n", repairErr)
			fmt.Fprintf(w, "  Fix: repair that file, then remove any %q line by hand.\\n", agent.MetadataDenyRule)
		case changed:
			fmt.Fprintf(w, "%s permissions: STALE RULE\\n", displayName)'''
new='''		// One pass: Repair reports whether it found the rule, so a separate
		// detect call would only read and parse the same file twice.
		//
		// A repair error is logged rather than printed. An agent whose config
		// will not parse never reaches here — AreHooksInstalled fails on it, so
		// GetAgentsWithHooksInstalled leaves it out — which leaves only write
		// failures, and printing "stale rule" for those would name the wrong
		// problem. (That a broken config goes unreported at all is a separate,
		// pre-existing gap: agentHookState.unchecked has no consumer.)
		changed, repairErr := agent.RepairRetiredMetadataDenyRule(ctx, ag)
		if repairErr != nil {
			logging.Warn(ctx, "could not remove retired deny rule",
				slog.String("agent", string(ag.Type())),
				slog.String("error", repairErr.Error()))
			continue
		}
		if changed {
			displayName := string(ag.Type())
			fmt.Fprintf(w, "%s permissions: STALE RULE\\n", displayName)'''
assert old in s
s=s.replace(old,new,1)
old2='''			fmt.Fprintln(w, "  ✓ Fixed: rule removed (your other deny rules are untouched).")
			fmt.Fprintln(w, "  The settings file changed — commit or revert it as you prefer.")
		}
	}
}'''
new2='''			fmt.Fprintln(w, "  ✓ Fixed: rule removed (your other deny rules are untouched).")
			fmt.Fprintln(w, "  The settings file changed — commit or revert it as you prefer.")
		}
	}
}'''
assert old2 in s
open(p,'w').write(s)
print("doctor branch simplified")
